#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<unsigned long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int mid_point = n / 2;
    vector<unsigned long long> half1, half2;

    // Generate all subset sums for the left half
    function<void(int, unsigned long long)> generate_sums_left = [&](int i, unsigned long long total) {
        if (i == mid_point) {
            half1.push_back(total);
        } else {
            generate_sums_left(i + 1, (total + a[i]) % m);
            generate_sums_left(i + 1, total);
        }
    };

    // Generate all subset sums for the right half
    function<void(int, unsigned long long)> generate_sums_right = [&](int i, unsigned long long total) {
        if (i == n) {
            half2.push_back(total);
        } else {
            generate_sums_right(i + 1, (total + a[i]) % m);
            generate_sums_right(i + 1, total);
        }
    };

    generate_sums_left(0, 0);
    generate_sums_right(mid_point, 0);

    // Remove duplicates and sort half1
    set<unsigned long long> set_half1(half1.begin(), half1.end());
    vector<unsigned long long> sorted_half1(set_half1.begin(), set_half1.end());

    unsigned long long best_total = 0;
    for (auto val : half2) {
        auto it = lower_bound(sorted_half1.begin(), sorted_half1.end(), m - val);
        if (it != sorted_half1.begin()) {
            --it;
            unsigned long long candidate = *it + val;
            if (candidate > best_total) {
                best_total = candidate;
            }
        }
    }

    cout << best_total << "\n";

    return 0;
}
